def compute(vars):
    comparison_year_value = vars["Comparison Year Value"]
    base_year_value = vars["Base Year Value"]
    multiplier = 100.0

    if comparison_year_value is None or base_year_value is None:
        return None
    if base_year_value == 0:
        return None

    percentage_change = (
        (comparison_year_value - base_year_value) / base_year_value * multiplier
    )

    return {
        "value": percentage_change,
        "trace": {
            "Comparison Year Value": comparison_year_value,
            "Base Year Value": base_year_value,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage",
            },
        },
    }
